+    if (action.id == "net.company.session.user_local_active") {
+        if (subject.session == "c1" && subject.user == "john" &&
+            subject.local == true && subject.active == true) {
+            return polkit.Result.YES;
+        } else {
+            return polkit.Result.NO;
+        }
+    }
+});
+
+polkit.addRule(function(action, subject) {
+    if (action.id == "net.company.session.no_pid") {
+        if (subject.session == "c1" && subject.pid == undefined) {
+            return polkit.Result.YES;
+        } else {
+            return polkit.Result.NO;
+        }
+    }
+});
+
